 'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import {readOpeningReview} from '@/lib/invoice-opening-review';
import {prepareOpeningReclassification,readOpeningReclassificationReceipt,readOpeningReclassificationStatus,loadPendingOpeningReclassification,savePendingOpeningReclassification,clearPendingOpeningReclassification} from '@/lib/invoice-opening-reclassification';
type Props={tenant:string;property:string;reservation:string;actor:string;disabled:boolean;options:unknown};
export function OpeningReclassificationAction(props:Props){return <Action key={[props.tenant,props.property,props.reservation,props.actor].join(':')} {...props}/>;}
function Action({disabled,options,...scope}:Props){
 const [review,setReview]=useState<ReturnType<typeof prepareOpeningReclassification>|null>(null),[pending,setPending]=useState<ReturnType<typeof prepareOpeningReclassification>|null>(null),[cancelConfirmed,setCancelConfirmed]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[consumed,setConsumed]=useState<unknown>(null);const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{setPending(loadPendingOpeningReclassification(sessionStorage,scope));}catch(e){setError(e instanceof Error?e.message:'Cannot recover correction.');}return()=>{alive.current=false;};},[scope.tenant,scope.property,scope.reservation,scope.actor]);
 let data:ReturnType<typeof readOpeningReview>|null=null;try{if(options)data=readOpeningReview(options,scope);}catch{}
 function prepare(form:FormData){try{if(loadPendingOpeningReclassification(sessionStorage,scope))throw Error('Resolve the saved correction first.');const lines=(data?.lines||[]).flatMap(l=>{const raw=String(form.get(l.source_key)||'').trim();if(!raw)return [];if(!/^(0|[1-9][0-9]{0,9})(\.[0-9]{1,2})?$/.test(raw))throw Error('Use at most two decimal places.');const [whole,fraction='']=raw.split('.');const n=BigInt(whole)*BigInt(100)+BigInt(fraction.padEnd(2,'0'));return n===BigInt(0)?[]:[{source_key:l.source_key,amount_minor:n.toString()}];});setReview(prepareOpeningReclassification(scope,crypto.randomUUID(),options,{reversal:String(form.get('reversal')),reason:String(form.get('reason')),lines}));setError('');setMessage('');}catch(e){setError(e instanceof Error?e.message:'Review correction amounts.');}}
 async function submit(status=false,cancel=false){if(lock.current||disabled||(!review&&!pending)||(cancel&&(!pending||!cancelConfirmed)))return;lock.current=true;setBusy(true);setError('');setMessage('');try{const request=pending||review!;const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen this stay.');if(!alive.current)return;
 if(!pending){savePendingOpeningReclassification(sessionStorage,scope,request);setPending(request);setReview(null);}
 const result=await hotelRpc<unknown>(cancel?'cancel_opening_reclassification_request':status?'opening_reclassification_status':'reclassify_opening_itemization',cancel?{p_tenant:scope.tenant,p_property:scope.property,p_request:request.args.p_request,p_confirmed:true}:status?{p_tenant:scope.tenant,p_property:scope.property,p_request:request.args.p_request}:request.args);
 const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Recover after signing in.');if(!alive.current)return;
 if(cancel){const r=result as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.request_id!==request.args.p_request||r.cancelled!==true||typeof r.replayed!=='boolean')throw Error('Cancellation receipt does not match this correction.');clearPendingOpeningReclassification(sessionStorage,scope,request.args.p_request);setPending(null);setReview(null);setCancelConfirmed(false);setConsumed(options);setMessage('Unrecorded correction cancelled. Refresh opening corrections.');return;}
 if(status){if(!readOpeningReclassificationStatus(result,request)){setMessage('No saved result found. Retry the original correction request.');return;}}else readOpeningReclassificationReceipt(result,request);
 clearPendingOpeningReclassification(sessionStorage,scope,request.args.p_request);setPending(null);setReview(null);setConsumed(options);setMessage('Category split revised. Refresh opening corrections and billable charges.');
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Correction interrupted. Check its saved result.');}finally{lock.current=false;if(alive.current)setBusy(false);}}
 const shown=pending||review;
 return <section className="pilot-settings"><h4>Revise opening category split</h4><p>Enter the complete replacement split for one recorded reversal. The total stays unchanged. Categories already invoiced may limit the change. Review service reporting separately after saving.</p>{!shown&&data&&options!==consumed&&data.reversals.some(r=>r.itemized&&r.classification_revision!==null)&&<form onSubmit={e=>{e.preventDefault();prepare(new FormData(e.currentTarget));}}><fieldset disabled={busy||disabled}><label className="field">Opening reversal<select name="reversal">{data.reversals.filter(r=>r.itemized&&r.classification_revision!==null).map(r=><option value={r.id} key={r.id}>{r.reference}: {usd(Number(r.amount_minor))}</option>)}</select></label>{data.lines.map(l=><label className="field" key={l.source_key}>Replacement amount for {l.description} (USD)<input name={l.source_key} inputMode="decimal" placeholder="0.00"/></label>)}<label className="field">Correction reason<input name="reason" required minLength={4} maxLength={500}/></label><button>Review replacement split</button></fieldset></form>}{shown&&<><p>Total correction: {usd(Number(shown.amount_minor))}</p><ul>{shown.args.p_lines.map(l=><li key={l.source_key}>{data?.lines.find(x=>x.source_key===l.source_key)?.description||l.source_key}: {usd(Number(l.amount_minor))}</li>)}</ul><p>{shown.args.p_reason}</p><button disabled={busy||disabled} onClick={()=>void submit()}>{pending?'Retry saved correction':'Confirm replacement split'}</button>{pending?<button disabled={busy||disabled} onClick={()=>void submit(true)}>Check correction result</button>:<button disabled={busy||disabled} onClick={()=>setReview(null)}>Edit correction split</button>}</>}{pending&&<><label><input type="checkbox" checked={cancelConfirmed} disabled={busy||disabled} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel only if this correction was not recorded</label><button disabled={busy||disabled||!cancelConfirmed} onClick={()=>void submit(false,true)}>Cancel unrecorded correction</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
